class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        i = 0
        indices = []
        result = [0] * n
        nums2 = sorted([(nums[idx], idx) for idx in range(n)])

        while i < n:
            if i == 0 or nums2[i][0] - nums2[i - 1][0] > limit:
                indices.append([])
            indices[-1].append(i)
            i += 1

        j = 0
        for index_list in indices:
            sorted_index = sorted(index_list)
            for j in range(len(index_list)):
                result[sorted_index[j]] = nums[index_list[j]]
            j += 1

        return result
